eventio::Json write_joint_source_capture_state(JointProblemBuilder&b,const std::filesystem::path&out){
 std::filesystem::create_directories(out);auto row=b.row,alpha=b.alpha;std::vector<std::uint32_t>path;std::vector<std::uint8_t>valid(b.packet.rows.size());std::size_t active=0,failed=0,protected_rows=0;eventio::Json invalid=eventio::Json::array(),invisible=eventio::Json::array();
 for(std::size_t i=0;i<b.packet.rows.size();++i){auto&o=b.packet.rows[i];path.push_back(o.path);if(!o.active)continue;++active;
  if(b.fixed_nuisance_shots.count(o.shot_id)){++protected_rows;valid[i]=1;continue;}
  JointObservation bare=o;bare.query.reset();bare.row=row[i];auto q=b.row_evaluation(i);q.observation=&bare;auto pp=b.model.pointers(q.layout);std::array<double,3>x;Eigen::Matrix3d J;
  if(!q.local_solution(pp.data(),b.station[i],&x,&J)){++failed;invalid.push_back(i);continue;}
  row[i]=x[1];valid[i]=1;if(!b.model.visibility(q.layout,b.station[i],row[i],pp.data()).visible())invisible.push_back(i);if(o.query){auto prediction=b.model.predict_explicit(q.layout,b.station[i],row[i],pp.data());auto nearest=closest_query_alpha(*o.query,prediction.uv,alpha[i]);if(std::isfinite(nearest.second))alpha[i]=nearest.first;}
  o.station=b.station[i];o.row=row[i];o.alpha=alpha[i];
 }
 b.row=row;b.alpha=alpha;
 auto write=[&](const char*name,const void*data,std::size_t size){std::ofstream f(out/name,std::ios::binary);f.write(static_cast<const char*>(data),size);if(!f)throw std::runtime_error("actual coarse state write failed");};
 write("station.f64",b.station.data(),b.station.size()*8);write("row.f64",row.data(),row.size()*8);write("alpha.f64",alpha.data(),alpha.size()*8);write("path.u32",path.data(),path.size()*4);write("RS_valid.u8",valid.data(),valid.size());
 {std::ofstream model(out/"model.json");model<<b.model.exact_json().dump(2);}
 eventio::Json files;for(const auto*name:{"station.f64","row.f64","alpha.f64","path.u32","RS_valid.u8","model.json"})files[name]={{"file",(out/name).string()},{"sha256",eventio::file_sha256(out/name)},{"bytes",std::filesystem::file_size(out/name)}};
 eventio::Json report={{"schema","rinkfit.actual_source_capture_state.v1"},{"source_packet_sha256",b.packet.source_hash},{"raw_rows",b.packet.rows.size()},{"active_rows",active},{"true_RS_invalid_rows",failed},{"invalid_rows",invalid},{"physical_visibility_invalid_rows",invisible.size()},{"invisible_row_ids",invisible},{"nonprotected_physical_visibility_checked",true},{"protected_physical_visibility_preserved_by_full_dependency_guard",true},{"fixed_shot_nuisance_rows_preserved",protected_rows},{"files",files},{"source_UV_E_W_and_frozen_Query_changed",false},{"source_pixel_coarse_objective_only",true},{"station_is_actual_coarse_solution_not_profiled_Query_replay",true},{"alpha_is_nearest_bounded_navigation_only",true},{"strict_Query_closure_passed",false},{"formal_Phase_I_II_passed",false}};
 std::ofstream receipt(out/"manifest.json");receipt<<report.dump(2);return report;
}
eventio::Json initialize_joint_query_witnesses(JointProblemBuilder&b,const std::vector<std::size_t>&rows,const std::filesystem::path&out,int threads){if(threads<1)throw std::runtime_error("query witness thread count");std::set<std::size_t>unique;const auto new_start=b.packet.source_json.at("new_source_start").get<std::size_t>();for(auto i:rows)if(i<new_start||i>=b.packet.rows.size()||!b.packet.rows[i].active||!b.packet.rows[i].query||!unique.insert(i).second)throw std::runtime_error("warm witness scope requires unique active new-source genuine Queries");std::filesystem::create_directories(out);std::atomic<std::size_t>next{0},valid{0},changed{0};std::vector<std::uint8_t>success(rows.size());double max_distance=0;std::mutex mutex;auto work=[&](){for(;;){const auto k=next.fetch_add(1);if(k>=rows.size())break;const auto i=rows[k];auto&o=b.packet.rows[i];try{auto l=o.layout(b.model);if(!o.station_allowed(b.model,o.path,b.station[i]))continue;auto pp=b.model.pointers(l);const auto pred=b.model.predict_for_al(l,b.station[i],b.row[i],pp.data());if(!pred.arithmetic_valid)continue;auto result=closest_query_alpha(*o.query,pred.uv,b.alpha[i]);if(!std::isfinite(result.second))continue;if(b.alpha[i]!=result.first)++changed;o.alpha=b.alpha[i]=result.first;success[k]=1;++valid;std::lock_guard<std::mutex>lock(mutex);max_distance=std::max(max_distance,result.second);}catch(...){}}};std::vector<std::thread>pool;for(int t=1;t<threads;++t)pool.emplace_back(work);work();for(auto&t:pool)t.join();std::vector<std::size_t>failed;for(std::size_t k=0;k<rows.size();++k)if(!success[k])failed.push_back(rows[k]);auto path=out/"alpha.f64";std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(b.alpha.data()),b.alpha.size()*8);f.close();eventio::Json report={{"schema","rinkfit.actual_warm_genuine_query_witness_initialization.v1"},{"source_packet_sha256",b.packet.source_hash},{"requested_rows",rows.size()},{"valid_numeric_witness_rows",valid.load()},{"failed_rows",failed},{"alpha_changed_rows",changed.load()},{"maximum_initial_profile_distance_px",max_distance},{"alpha",{{"file",path.string()},{"sha256",eventio::file_sha256(path)},{"dtype","<f8"},{"shape",{b.alpha.size()}}}},{"existing_path_station_and_explicit_row_preserved",true},{"source_UV_E_W_or_actual_frozen_Query_changed",false},{"source_RS_Query_or_physical_constraint_closure_claimed",false},{"meaning","numerical warm alpha within original actual source window; all exact Query/RS/E/finite constraints remain in common PHR"}};std::ofstream receipt(out/"receipt.json");receipt<<report.dump(2);return report;}

